import styled from '@emotion/styled';

export const StyledTrainingHubWrapper = styled.div({
  width: '1256px',
  margin: '0 auto',
});

export const StyledTrainingHubHome = styled.div({
  display: 'flex',
  flexDirection: 'column',
  width: '100%',
  gap: '1rem',
  padding: '24px 0px 0px 0px',
});

export const StyledTrainingHubHomeCardsContainer = styled.div({
  display: 'flex',
  flexDirection: 'row',
  gap: '16px',
  paddingBottom: '24px',
});

export const StyledToolsContainer = styled.div({
  width: '100%',
  display: 'flex',
  gap: '8px',
  justifyContent: 'flex-start',
  paddingBottom: '56px',
});
